<script setup lang="ts">
import {ref,computed,onMounted} from 'vue'
import {Settings2,RefreshCw,Award} from 'lucide-vue-next'
import {api,cash,date,notify,type Row} from '../lib'
import DataTable from './DataTable.vue'
import Modal from './Modal.vue'
import TierEditor from './TierEditor.vue'
const emit=defineEmits<{'changed':[]}>()
const data=ref<Row>({}),error=ref(''),loading=ref(false),rules=ref(false),includeAdmin=ref(false),filter=ref(''),selected=ref<Row|null>(null),code=ref(''),until=ref(''),reason=ref(''),busy=ref(false)
const rows=computed(()=>(data.value.items||[]).filter((u:Row)=>(includeAdmin.value||u.role!=='admin')&&(!filter.value||u.membership.current.code===filter.value)))
async function load(){loading.value=true;try{data.value=await api('/admin/membership');error.value=''}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
function edit(row:Row){selected.value=row;code.value=row.membership.source==='manual'?row.membership.current.code:'';until.value=row.membership.until?new Date(new Date(row.membership.until).getTime()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16):'';reason.value=''}
async function save(){if(busy.value||!selected.value)return;busy.value=true;try{await api('/admin/users/'+selected.value.id+'/membership','PUT',{code:code.value,until:code.value&&until.value?new Date(until.value).toISOString():null,reason:reason.value});selected.value=null;notify('会员等级已更新');await load();emit('changed')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
onMounted(load)
</script>
<template><div :aria-busy="loading"><div class="filter-strip"><span class="pill"><Award :size="15"/>{{data.customers||0}} 位客户</span><button class="btn secondary" @click="rules=!rules"><Settings2 :size="16"/>{{rules?'收起等级规则':'等级规则'}}</button><button class="btn secondary" @click="load" :disabled="loading"><RefreshCw :size="16"/>刷新会员</button></div><div v-if="error" class="alert danger">{{error}}</div><div v-if="rules&&data.config" class="panel form-panel"><TierEditor :key="JSON.stringify(data.config)" :value="data.config" @saved="load();emit('changed')"/></div><div class="membership-distribution"><button v-for="t in data.config?.items" :key="t.code" class="panel" :class="{selected:filter===t.code}" @click="filter=filter===t.code?'':t.code"><span>{{t.code}} · {{t.name}}</span><b>{{data.distribution?.[t.code]||0}}<small> 位</small></b><span>减免 {{100-t.discount}}%</span></button></div><div class="filter-strip"><select v-model="filter" aria-label="筛选会员等级"><option value="">全部等级</option><option v-for="t in data.config?.items" :key="t.code" :value="t.code">{{t.name}}</option></select><label class="checkbox-label"><input v-model="includeAdmin" type="checkbox"/>包含管理员</label><span class="muted small">统计默认排除管理员 · 支持临时或长期指定等级</span></div><div class="panel"><DataTable :rows="rows" :columns="[{key:'email',label:'客户'},{key:'membership',label:'当前等级'},{key:'spent',label:'累计有效消费'},{key:'automatic',label:'自动等级'},{key:'fee_override',label:'专属单价'},{key:'until',label:'指定有效期'},{key:'action',label:'操作'}]"><template #email="{row}"><b>{{row.name}}</b><small>{{row.email}}</small></template><template #membership="{row}"><span class="badge active">{{row.membership.current.code}} · {{row.membership.current.name}}</span><small>{{row.membership.source==='manual'?'运营指定':'消费自动'}} · 减免 {{100-row.membership.current.discount}}%</small></template><template #spent="{row}">{{cash(row.spent)}} R</template><template #automatic="{row}">{{row.membership.automatic.name}}</template><template #fee_override="{row}">{{row.fee_override==null?'按会员等级':cash(row.fee_override)+' R'}}</template><template #until="{row}">{{row.membership.source==='manual'?(row.membership.until?date(row.membership.until):'长期'):'—'}}</template><template #action="{row}"><button class="text-btn" @click="edit(row)">调整等级</button></template></DataTable></div><Modal v-if="selected" title="调整会员等级" @close="selected=null"><form @submit.prevent="save"><p>{{selected.email}}</p><label>等级来源<select v-model="code"><option value="">恢复按消费自动升级</option><option v-for="t in data.config.items" :key="t.code" :value="t.code">{{t.code}} · {{t.name}}</option></select></label><label v-if="code">有效至（留空为长期）<input v-model="until" type="datetime-local"/><small>到期后立即按实际累计消费恢复自动等级。</small></label><label>调整原因<textarea v-model="reason" required minlength="2" maxlength="160" rows="3"></textarea></label><div v-if="error" class="alert danger">{{error}}</div><button class="btn primary" :disabled="busy">保存会员调整</button></form></Modal></div></template>
